#!/bin/bash
# Build, Flash, and Monitor script for theSpeaker (3 boards)
# Auto-generated by Embedded Generator

set -e

PORT="${1:-/dev/ttyUSB0}"
BAUD="${2:-115200}"

# Check if ESP-IDF is set up
if [ -z "$IDF_PATH" ]; then
    echo "ERROR: ESP-IDF environment not set up."
    echo "Please run: . $HOME/esp/esp-idf/export.sh"
    exit 1
fi

echo "=========================================="
echo "  theSpeaker (3 boards)"
echo "  Target: esp32"
echo "  Port: $PORT"
echo "=========================================="

# Set target (only needed once, but safe to run again)
idf.py set-target esp32 2>/dev/null || true

# Build
echo ""
echo "[1/3] Building..."
idf.py build

# Erase flash and NVS (clean start)
echo ""
echo "[2/4] Erasing flash and NVS..."
python3 -m esptool --port "$PORT" --baud "$BAUD" erase_flash
sleep 1

# Flash
echo ""
echo "[3/4] Flashing to $PORT..."
idf.py -p "$PORT" -b "$BAUD" flash

# Monitor
echo ""
echo "[4/4] Starting monitor (Ctrl+] to exit)..."
idf.py -p "$PORT" -b "$BAUD" monitor
